<script src="aims-admin-shell.js?v=44" defer></script><script src="vendor/leaflet/leaflet.js" defer></script><script src="aims-mileage.js?v=44" defer></script></head><body class="aims-unified"><?php require_once __DIR__.'/admin-shell-static.php';aims_render_admin_shell();?><main class="km-wrap">
<header class="km-head"><div><small>AIMS FLOW · JÁRMŰELSZÁMOLÁS</small><h1>Kilométer és árrés</h1><p>A rögzített utak, megbízások és hazautak egy helyen.</p></div><button type="button" onclick="window.print()" class="km-print">Nyomtatás / PDF</button></header>
<?php if($message):?><p class="km-notice" role="status"><?=km_h($message)?></p><?php endif;?><?php if($error):?><p class="km-notice km-negative" role="alert"><?=km_h($error)?></p><?php endif;?>
<form method="get" class="km-filter" id="kmFilter"><label>Ettől<input type="date" name="from" required value="<?=km_h($from)?>"></label><label>Eddig, ezt a napot is beleértve<input type="date" name="to" required value="<?=km_h($to)?>"></label><label>Rendszám<select name="plate"><option value="">Összes rendszám</option><?php foreach($vehicles as $v):?><option value="<?=km_h($v['plate'])?>" <?=$plate===$v['plate']?'selected':''?>><?=km_h($v['plate'])?></option><?php endforeach;?></select></label><label>Sofőr<select name="driver"><option value="">Összes sofőr</option><?php foreach($drivers as $d):?><option value="<?=km_h($d['flow_id'])?>" <?=$flow===$d['flow_id']?'selected':''?>><?=km_h($d['driver_name'].' · '.$d['flow_id'])?></option><?php endforeach;?></select></label><button type="submit">Riport készítése</button>
<div class="km-shortcuts"><button type="button" data-range="today">Ma</button><button type="button" data-range="yesterday">Tegnap</button><button type="button" data-range="three">Utolsó 3 nap</button><button type="button" data-range="month">Ez a hónap</button><button type="button" data-range="previous">Előző hónap</button><span>Időzóna: Budapest</span></div></form>
<nav class="km-links" aria-label="Riportok ugyanerről az időszakról"><a href="aims-flow-monthly-report.php?<?=km_h(http_build_query($params))?>">Országidő és jelenlét</a><a href="aims-flow-eco.php?<?=km_h(http_build_query($params))?>">ECO</a><a href="foreign-stay-report.php?<?=km_h(http_build_query($params))?>">Külföldi tartózkodás</a></nav>
<?php if($report):?>
<section class="km-summary" aria-label="Időszaki összesítés"><div><small>Megtett GPS km</small><b><?=km_n($totals['actual'])?></b></div><div><small>Levonható hazautak</small><b><?=km_n($totals['home'])?> km</b></div><div><small>Korrigált kilométer</small><b><?=km_n($totals['net'])?> km</b></div><div><small>Megbízás szerinti km</small><b><?=km_n($totals['planned'])?><?=$totals['missingKm']?' *':''?></b></div><div><small>Ismert nettó bevétel</small><b><?=km_money($totals['revenue'])?></b></div><div><small>Önköltség · 0,30 €/km</small><b><?=km_money($totals['cost'])?></b></div><div><small>Árrés a teljes futás után</small><b><?=km_money($totals['margin'])?></b></div></section>
<p class="km-explanation">Korrigált km = megtett GPS-km − igazolt hazautak. Eltérés = korrigált km − megbízás szerinti km. Önköltség = <b>az összes megtett km × 0,30 €</b>, a hazautakkal együtt. Árrés = nettó bevétel − önköltség. Az önköltség minden költséget tartalmaz, ezért az üzemanyagot és útdíjat nem számoljuk hozzá újra.</p>
<?php if($totals['issues']||$totals['missingRevenue']||$totals['missingKm']):?><p class="km-notice">* Az összesítés hiányos adatot tartalmaz. Hiányzó bevétel vagy ellenőrizendő GPS esetén az árrést nem tekintjük lezártnak. Az ismert értékek látszanak; a hiányzó összeg nem nulla.</p><?php endif;?>
<div class="km-section"><h2>Rendszámonkénti összesítő</h2><a href="?<?=km_h(http_build_query($params+['download'=>'summary']))?>">Összesítő CSV</a></div><?php km_table($report['summary'],false);?>
<div class="km-section"><h2>Napi bontás</h2><a href="?<?=km_h(http_build_query($params+['download'=>'daily']))?>">Napi CSV</a></div><?php km_table($report['daily'],true);?>
<p class="km-explanation">A megbízási kilométer és a bevétel a teljesítés napjára kerül; a GPS-km a tényleges napjára. A napváltáson átnyúló GPS-szakaszokat időarányosan bontjuk. A GPS-ből számított útvonal becslés; az összevethető km-óra-adatoktól való jelentős eltérést jelezzük.</p>
<div class="km-section"><h2>Utolsó lerakó → lakóhely</h2><a href="?<?=km_h(http_build_query($params+['download'=>'trips']))?>">Hazautak CSV</a></div><div class="km-table"><table><thead><tr><th>Rendszám / sofőr</th><th>Utolsó lerakó</th><th>Lerakó lezárása</th><th>Hazaérkezés</th><th>Hazaút km</th><th>Ebből az időszakban</th><th>Levonás</th></tr></thead><tbody><?php if(!$report['trips']):?><tr><td colspan="7">Nincs felismert hazaút. Ellenőrizd a lakóhelyet, a lezárt lerakót és a GPS-adatokat.</td></tr><?php endif;?><?php foreach($report['trips'] as $t):?><tr><td><b><?=km_h($t['plate'])?></b><small><?=km_h($t['driverName'])?></small></td><td><?=km_h($t['reference'])?></td><td><?=km_h((new DateTimeImmutable('@'.$t['start']))->setTimezone($tz)->format('Y-m-d H:i'))?></td><td><?=km_h((new DateTimeImmutable('@'.$t['arrival']))->setTimezone($tz)->format('Y-m-d H:i'))?></td><td><?=km_n($t['km'])?></td><td><?=km_n($t['periodKm'])?></td><td><?=km_h($t['reason'])?></td></tr><?php endforeach;?></tbody></table></div>
<p class="km-explanation">Hazaérkezéshez legalább két megfelelő GPS-jel és két perc a lakóhely körzetében szükséges. A hazafelé tartó úton rögzített új felrakó megszakítja a hazautat. GPS-kimaradásból nem készítünk levonható kilométert. Az automatikus felismerés a riport megnyitásakor a már meglévő nyomkövetési adatokból fut.</p>
<div class="km-section"><h2>Időszaki megbízások</h2><a href="#finance">Kilométer / bevétel rögzítése</a></div><div class="km-table"><table><thead><tr><th>Nap</th><th>Referencia</th><th>Rendszám</th><th>Megbízás km</th><th>Nettó bevétel</th><th></th></tr></thead><tbody><?php foreach($report['jobs'] as $j):?><tr><td><?=km_h($j['date'])?></td><td><?=km_h($j['reference'])?></td><td><?=km_h($j['plate'])?></td><td><?=km_n($j['plannedKm'])?></td><td><?=km_money($j['revenueCents']===null?null:(int)$j['revenueCents'])?></td><td><button type="button" data-edit-job="<?=$j['id']?>">Szerkesztés</button></td></tr><?php endforeach;?></tbody></table></div>
<?php endif;?>
<section class="km-config" id="homes"><h2>Sofőr lakóhelye rendszám szerint</h2><p>A címet írd be, a pontos helyet jelöld ki a térképen, vagy használd a jármű legutóbbi GPS-helyét, amikor a sofőr otthon van. A kezdőnap megadása megőrzi a korábbi sofőr és lakóhely előzményeit.</p>
<form method="post" class="km-form" id="kmHomeForm"><input type="hidden" name="csrf" value="<?=km_h($csrf)?>"><input type="hidden" name="action" value="home"><label>Rendszám<select name="vehicle_id" required id="kmVehicle"><option value="">Válassz rendszámot</option><?php foreach($vehicles as $v):?><option value="<?=$v['id']?>" data-lat="<?=km_h($v['latitude'])?>" data-lng="<?=km_h($v['longitude'])?>" data-time="<?=km_h($v['captured_at'])?>"><?=km_h($v['plate'])?></option><?php endforeach;?></select></label><label>Sofőr<select name="flow_id"><option value="">A rendszám minden sofőrjére</option><?php foreach($drivers as $d):?><option value="<?=km_h($d['flow_id'])?>"><?=km_h($d['driver_name'].' · '.$d['flow_id'])?></option><?php endforeach;?></select></label><label class="km-wide">Lakóhely pontos címe<input name="address" required maxlength="500" autocomplete="off" placeholder="Irányítószám, település, utca, házszám"></label><label>Érvényes ettől a naptól<input type="date" name="valid_from" required value="<?=$today->format('Y-m-d')?>"></label><label>Érzékelési körzet, méter<input type="number" name="radius_m" min="50" max="1000" step="10" value="200" required></label><label>Szélesség<input name="latitude" type="number" step="any" min="-90" max="90" required id="kmLat"></label><label>Hosszúság<input name="longitude" type="number" step="any" min="-180" max="180" required id="kmLng"></label><div class="km-wide km-buttons"><button type="button" id="kmUseGps">Legutóbbi GPS-hely átvétele</button><button type="button" id="kmOpenMap">Hely kijelölése térképen</button><span id="kmLocationStatus" role="status"></span></div><div id="kmMap" class="km-wide" hidden></div><div class="km-wide"><button type="submit">Lakóhely mentése</button></div></form>
<div class="km-table"><table><thead><tr><th>Rendszám</th><th>Sofőr</th><th>Cím</th><th>Körzet</th><th>GPS-helyzet</th><th>Érvényesség</th></tr></thead><tbody><?php foreach($homes as $h):
 $presence='Nincs friss GPS-adat';
 foreach($vehicles as $v){if((int)$v['id']!==(int)$h['vehicle_id'])continue;$seen=aims_mileage_time($v['captured_at']);
 if($seen!==null&&$seen>=aims_mileage_time($h['valid_from'])&&($h['valid_until']===null||$seen<aims_mileage_time($h['valid_until']))&&$v['accuracy']!==null&&(float)$v['accuracy']<=100){
 $presence=(time()-$seen>900?'Régi GPS: ':'').(aims_distance_m((float)$v['latitude'],(float)$v['longitude'],(float)$h['latitude'],(float)$h['longitude'])<=(float)$h['radius_m']?'Lakóhely körzetében':'Lakóhelyen kívül');
 $presence.=' · '.(new DateTimeImmutable('@'.$seen))->setTimezone($tz)->format('m-d H:i');}break;}
 ?><tr><td><?=km_h($h['plate'])?></td><td><?=km_h($h['flow_id']?:'Minden sofőr')?></td><td><?=km_h($h['address'])?></td><td><?=$h['radius_m']?> m</td><td><?=km_h($presence)?></td><td><?=km_h((new DateTimeImmutable($h['valid_from']))->setTimezone($tz)->format('Y-m-d'))?> → <?=km_h($h['valid_until']?(new DateTimeImmutable($h['valid_until']))->setTimezone($tz)->format('Y-m-d H:i'):'visszavonásig')?></td></tr><?php endforeach;?></tbody></table></div></section>
